function test(name,fn){try{fn();console.log('PASS '+name);passed++;}catch(e){console.error('FAIL '+name+': '+e.message);failed++;}}
function setup(id='basics'){const e=env();assert.ok(e.c.JPWLearningGuide,'guide API missing');e.add('#dash');e.add('#brandHomeBtn');e.c.JPWLearningGuide.start(id);e.flush();return e;}
test('catalog and controller exist',()=>{const e=env();assert.ok(e.c.JPWLearningCatalog,'catalog missing');assert.ok(e.c.JPWLearningGuide,'guide missing');});
test('catalog is immutable and all IDs/copy/required tracks are complete',()=>{const c=env().c.JPWLearningCatalog;assert.ok(c);assert.equal(Object.isFrozen(c),true);assert.deepEqual(Array.from(c.tracks,t=>t.id),['basics','personal-finance','forex','research','tools','alladin','general']);const ids=new Set();for(const t of c.tracks){assert.ok(t.steps.length>=2);for(const s of t.steps){assert.ok(s.id.startsWith(t.id+'-'));assert.ok(!ids.has(s.id));ids.add(s.id);for(const key of ['title','objective','instruction','expected'])assert.ok(s[key]?.length>15,s.id+' '+key);}}});
test('readiness never credits orientation until explicit acknowledgment',()=>{const e=setup();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['basics-home'],undefined);e.c.cb.understand();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['basics-home'].orientation,'seen');});
test('read acknowledgment and skip never claim practice',()=>{const e=setup();e.c.cb.understand();e.c.cb.skip();const records=e.c.JPWLearningGuide.snapshot().progress.steps;assert.equal(records['basics-home'].practice,null);assert.ok(Object.values(records).some(s=>s.orientation==='skipped'));});
test('snapshot is defensive and excludes live personal state',()=>{const e=setup();const s=e.c.JPWLearningGuide.snapshot();s.progress.steps.bad={orientation:'seen',practice:'confirmed'};assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps.bad,undefined);assert.ok(!JSON.stringify(s).includes('personalFinance'));});
test('pause invalidates queued anchor work and resume rechecks live target',()=>{const e=setup();e.c.cb.pause();e.els.get('#dash').hidden=true;e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);e.c.JPWLearningGuide.resume();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);});
test('foreign accepted route pauses without credit or navigation back',()=>{const e=setup();e.route({canonical:'tools-calendar',primary:'tools',screen:'tools',localView:{surface:'tools',view:'calendar'}});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['basics-home'],undefined);});
test('frozen Alladin pauses without changing availability',()=>{const e=setup('alladin');assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWModuleAvailability.canAccess('alladin'),false);});
test('incompatible bytes survive every action until explicit restart',()=>{const e=env('{future:true}');assert.ok(e.c.JPWLearningGuide);e.c.JPWLearningGuide.start('basics');e.flush();assert.equal(e.data.get('jpwealth_learning_guide_v1'),'{future:true}');assert.equal(e.writes(),0);e.c.JPWLearningGuide.restart();assert.notEqual(e.data.get('jpwealth_learning_guide_v1'),'{future:true}');});
test('refused guide storage stays honest in memory and preserves financial bytes',()=>{const e=env();e.refuse();e.add('#dash');e.add('#brandHomeBtn');e.c.JPWLearningGuide.start('basics');e.flush();e.c.cb.understand();assert.equal(e.c.JPWLearningGuide.snapshot().storage,'memory');assert.equal(e.data.get('jpwealth_v9_state'),'{"personalFinance":{"months":{}},"mvpNotes":{"items":[]}}');});
test('external progress change pauses/reloads without navigating',()=>{const e=setup();e.data.set('jpwealth_learning_guide_v1',null);e.emit('storage',{key:'jpwealth_learning_guide_v1'});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWNavigation.current().canonical,'dashboard');});
test('session disposal prevents stale callbacks writing reset progress',()=>{const e=setup();e.c.JPWLearningGuide.disposeForSession();e.data.delete('jpwealth_learning_guide_v1');const n=e.writes();e.flush();assert.equal(e.writes(),n);assert.equal(e.data.has('jpwealth_learning_guide_v1'),false);});
test('practice needs original targeted fresh confirmed scoped write',()=>{const e=setup('personal-finance');const track=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='personal-finance');const ix=track.steps.findIndex(s=>s.practice==='budget');for(let i=0;i<ix;i++)e.c.cb.skip();e.add('#finpesBudgetRoot');const field=e.add('[data-fi-campo],[data-fe-campo]');field.dataset={fiCampo:'name',fiId:'r1'};field.value='Minha receita';e.data.set('jpwealth_v9_state',JSON.stringify({personalFinance:{months:{'2026-10':{incomes:[{id:'r1',name:'Antes'}]}}}}));e.c.cb.go();e.flush();let apply=false;field.addEventListener('change',()=>{if(apply){e.data.set('jpwealth_v9_state',JSON.stringify({personalFinance:{months:{'2026-10':{incomes:[{id:'r1',name:'Minha receita'}]}}}}));e.setLast({status:'CONFIRMED',reason:'READBACK_MATCH',context:'ctx',epoch:1,at:'newer'});}});e.c.cb.practice();e.flush();field.emit('change');e.flush();assert.notEqual(e.c.JPWLearningGuide.snapshot().progress.steps[track.steps[ix].id]?.practice,'confirmed');e.setLast({status:'CONFIRMED',reason:'READBACK_MATCH',context:'ctx',epoch:1,at:'fresh'});apply=true;field.emit('change');e.data.set('jpwealth_v9_state',JSON.stringify({personalFinance:{months:{'2026-10':{incomes:[{id:'r1',name:'Minha receita'}]}}}}));e.setLast({status:'CONFIRMED',reason:'READBACK_MATCH',context:'ctx',epoch:1,at:'newer'});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps[track.steps[ix].id].practice,'confirmed');});
test('desktop navigation remains readable when compact toggle is hidden',()=>{const e=setup();e.add('[data-shell-menu-toggle]').hidden=true;e.add('[data-route="dashboard"]');e.c.cb.skip();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);});
test('review and skipping retain prior confirmed practice',()=>{const e=env();const d=e.c.JPWLearningProgress.empty(e.c.JPWLearningCatalog);d.trackId='personal-finance';d.stepId='personal-finance-budget';d.steps['personal-finance-budget']={orientation:'seen',practice:'confirmed'};e.data.set('jpwealth_learning_guide_v1',JSON.stringify(d));e.emit('storage',{key:'jpwealth_learning_guide_v1'});e.add('#finpesOverviewRoot');e.add('#finpesBudgetRoot');e.c.JPWLearningGuide.start('personal-finance');e.flush();e.c.cb.skip();e.flush();e.c.cb.skip();const r=e.c.JPWLearningGuide.snapshot().progress.steps['personal-finance-budget'];assert.equal(r.orientation,'seen');assert.equal(r.practice,'confirmed');});
test('actual view chooses owned host and rejects unrelated nested dialogs',()=>{const e=env();const dialogs=[];const owned={id:'settingsModal',hidden:false,disabled:false,closest:()=>null,getClientRects:()=>[{}],contains:el=>el===target};const foreign={...owned,id:'foreign',contains:()=>false};const target={closest:()=>owned};e.c.document.querySelectorAll=()=>dialogs;e.c.JPWLearningView=null;vm.runInContext(fs.readFileSync(new URL('src/js/40-app/27-learning-view.js',base),'utf8'),e.c);dialogs.push(owned);assert.equal(e.c.JPWLearningView.selectHost(target,{}).host,owned);dialogs.push(foreign);assert.equal(e.c.JPWLearningView.selectHost(target,{}).foreign,true);});
test('compact menu opening migrates to the native menu host',()=>{const e=setup();e.c.shellUI={open:false};const menu=e.add('#appSidebar');e.c.shellMenuRoot=()=>menu;const toggle=e.add('[data-shell-menu-toggle]');e.c.cb.skip();e.flush();e.c.JPWLearningView.selectHost=target=>({host:e.c.document.body,foreign:e.c.shellUI.open&&target===toggle});e.c.shellUI.open=true;e.mutate();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);assert.equal(e.c.model.anchor,menu);});
test('guide refuses to leave a dirty settings profile',()=>{const e=env();e.add('#settingsModal');const account=e.add('[data-settings-panel="account"]');const appearance=e.add('[data-settings-panel="appearance"]');e.c.settingsProfileState={editing:true,draft:{displayName:'unsaved'},confirmed:{displayName:'saved'}};e.c.settingsState={open:true,active:'account'};e.c.JPWLearningGuide.start('general');e.flush();const t=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='general');const i=t.steps.findIndex(s=>s.destination?.settings==='appearance');for(let n=0;n<i;n++)e.c.cb.skip();e.flush();assert.equal(e.c.opened,undefined);assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.settingsProfileState.draft.displayName,'unsaved');});
function notesEnv(outcome='CONFIRMED',trusted=true){const e=env();e.add('#headerNotesBtn');e.add('#mvpNotesOverlay');const save=e.add('#mvpNotesSaveBtn');save.addEventListener('click',()=>{e.setLast({status:outcome,reason:outcome==='CONFIRMED'?'READBACK_MATCH':'FAIL',context:'ctx',epoch:1,at:'new'});if(outcome==='CONFIRMED'){e.data.set('jpwealth_v9_state',JSON.stringify({mvpNotes:{items:[{id:'n1',content:'Minha nota'}]}}));e.c.mvpNotesUI.draftDirty=false;}});e.c.JPWLearningGuide.start('general');e.flush();e.c.cb.skip();e.flush();e.c.cb.practice();save.emit('click',{isTrusted:trusted});e.flush();return e;}
test('Notes save confirms scoped fresh original persistence',()=>{const e=notesEnv();assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['general-notes-save'].practice,'confirmed');assert.ok(!JSON.stringify(e.c.JPWLearningGuide.snapshot()).includes('Minha nota'));});
test('untrusted and unknown Notes writes never confirm practice',()=>{for(const e of [notesEnv('UNKNOWN'),notesEnv('CONFIRMED',false)])assert.notEqual(e.c.JPWLearningGuide.snapshot().progress.steps['general-notes-save']?.practice,'confirmed');});
test('concurrent own progress update pauses rather than overwriting other cursor',()=>{const e=setup();const other=e.c.JPWLearningProgress.empty(e.c.JPWLearningCatalog);other.trackId='tools';other.stepId='tools-calendar';e.data.set('jpwealth_learning_guide_v1',JSON.stringify(other));e.c.cb.understand();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(JSON.parse(e.data.get('jpwealth_learning_guide_v1')).trackId,'tools');});
test('base epoch storage change pauses and invalidates pending observations',()=>{const e=setup();e.emit('storage',{key:'jpwealth_base_epoch_v1'});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);});
test('practice can confirm first fresh save after an older receipt epoch',()=>{const e=env();e.setLast({status:'REFUSED',reason:'NOT_ATTEMPTED',context:'ctx',epoch:0,at:null});e.add('#headerNotesBtn');e.add('#mvpNotesOverlay');const save=e.add('#mvpNotesSaveBtn');save.addEventListener('click',()=>{e.data.set('jpwealth_v9_state',JSON.stringify({mvpNotes:{items:[{id:'n1',content:'Minha nota'}]}}));e.c.mvpNotesUI.draftDirty=false;e.setLast({status:'CONFIRMED',reason:'READBACK_MATCH',context:'ctx',epoch:1,at:'fresh'});});e.c.JPWLearningGuide.start('general');e.flush();e.c.cb.skip();e.flush();e.c.cb.practice();save.emit('click');assert.equal(e.c.JPWLearningGuide.snapshot().progress.steps['general-notes-save']?.practice,'confirmed');});
test('concurrent refusal never presents ready coach for reloaded cursor',()=>{const e=setup();const other=e.c.JPWLearningProgress.empty(e.c.JPWLearningCatalog);other.trackId='tools';other.stepId='tools-calendar';e.data.set('jpwealth_learning_guide_v1',JSON.stringify(other));e.c.cb.understand();assert.notEqual(e.c.model?.status,'ready');});
test('Alladin destinations match current real tab keys',()=>{const e=env();const source=fs.readFileSync(new URL('index.html',base),'utf8');const tabs=new Set([...source.matchAll(/data-alladin-view="([^"]+)"/g)].map(m=>m[1]));for(const step of e.c.JPWLearningCatalog.tracks.find(t=>t.id==='alladin').steps)if(step.destination?.alladin)assert.ok(tabs.has(step.destination.alladin),step.id);});
test('completed observed action is consumed without repeated progress writes',()=>{const e=setup();const toggle=e.add('[data-shell-menu-toggle]');toggle.closest=selector=>selector.includes('shell-menu-toggle')?toggle:null;e.c.cb.skip();e.flush();toggle.setAttribute('aria-expanded','true');e.emit('click',{isTrusted:true,target:toggle});e.flush();const n=e.writes();e.mutate();e.flush();assert.equal(e.writes(),n);});
test('a rapid foreign route followed by return still pauses the accepted foreign visit',()=>{const e=setup();e.route({canonical:'tools-calendar',primary:'tools',screen:'tools',localView:{surface:'tools',view:'calendar'}});e.route({canonical:'dashboard',primary:'dashboard',screen:'dash',localView:null});e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);});
test('session disposal removes lifecycle storage and native step listeners',()=>{const e=setup();assert.ok(e.listenerCount('storage')>0);e.c.JPWLearningGuide.disposeForSession();assert.equal(e.listenerCount('storage'),0);assert.equal(e.listenerCount('keydown'),0);assert.equal(e.listenerCount('click'),0);});
test('Notes-to-Settings transition teaches original close in reachable owned host',()=>{const e=env();e.add('#headerNotesBtn');const notes=e.add('#mvpNotesOverlay');const close=e.add('#mvpNotesCloseBtn');e.c.JPWLearningGuide.start('general');e.flush();e.c.cb.skip();e.flush();e.c.JPWLearningView.selectHost=target=>({host:e.c.document.body,foreign:!notes.hidden&&target!==close});e.c.cb.skip();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.model?.anchor,close);assert.ok(e.c.model.notice.includes('controles originais'));notes.hidden=true;close.hidden=true;e.mutate();e.flush();assert.equal(e.c.model?.status,'paused');assert.equal(e.c.model?.anchor,null);});
test('Settings checklist uses real native dialog instead of invisible parent leaf',()=>{const e=env();const track=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='general');const ix=track.steps.findIndex(s=>s.destination?.settings==='tool-check');const dialog=e.add('#forexChecklistDialog');dialog.open=true;const grid=e.add('#checkWidgetGrid');e.c.JPWLearningGuide.start('general');e.flush();for(let n=0;n<ix;n++)e.c.cb.skip();e.flush();assert.equal(e.c.JPWLearningGuide.snapshot().stepId,'general-settings-tool-check');assert.equal(e.c.JPWLearningGuide.snapshot().paused,false);assert.equal(e.c.model.anchor,grid);});
test('central distinguishes seen and skipped orientations',()=>{const e=setup();e.c.cb.skip();const track=e.c.centerModel.tracks.find(t=>t.id==='basics');assert.equal(track.seen,0);assert.equal(track.skipped,1);assert.equal(track.practiced,0);});
test('native checklist exit restores reachable coach in original Settings owner',()=>{const e=env();const track=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='general');const ix=track.steps.findIndex(s=>s.destination?.settings==='tool-check');const dialog=e.add('#forexChecklistDialog');dialog.open=true;e.add('#checkWidgetGrid');const close=e.add('#forexChecklistClose');const title=e.add('#settingsPageTitle');e.c.JPWLearningGuide.start('general');e.flush();for(let n=0;n<ix;n++)e.c.cb.skip();e.flush();e.c.JPWLearningView.selectHost=target=>({host:e.c.document.body,foreign:dialog.open&&target!==close});e.c.cb.skip();e.flush();assert.equal(e.c.model.anchor,close);dialog.open=false;close.hidden=true;e.mutate();e.flush();assert.equal(e.c.model.status,'paused');assert.equal(e.c.model.anchor,title);});
test('beginner basics covers welcome choices, breadcrumb and financial local persistence modes',()=>{const e=env();const t=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='basics');const text=t.steps.map(s=>s.instruction).join(' ');for(const term of ['Começar do zero','Restaurar Backup Completo','Conhecer o app','origem','rascunho','salva ao sair'])assert.ok(text.includes(term),term);assert.ok(t.steps.some(s=>s.anchor==='#shellLocation'));});
test('beginner Finance points to native income/expense creation and distinguishes planned/actual fields',()=>{const e=env();const text=e.c.JPWLearningCatalog.tracks.find(t=>t.id==='personal-finance').steps.map(s=>s.instruction).join(' ');for(const term of ['+ Adicionar receita','+ Adicionar despesa','Projetado','Recebido','Previsto','Fora cartão','Cartão','Cancelar'])assert.ok(text.includes(term),term);});

function conflictDocument(e){const d=e.c.JPWLearningProgress.empty(e.c.JPWLearningCatalog);d.trackId='tools';d.stepId='tools-calendar';return JSON.stringify(d);}
for(const command of ['skip','next','back','start','go','understand'])test('expectedRaw conflict aborts entire '+command+' command',()=>{
 const e=setup();e.add('[data-shell-menu-toggle]');e.add('#shellLocation');
 if(command==='go'){e.route({canonical:'tools-normative',primary:'tools',screen:'tools',localView:{surface:'tools',view:'normative'}});e.flush();}
 if(command==='next'){e.c.cb.understand();}
 if(command==='back'){e.c.cb.skip();e.flush();}
 const other=conflictDocument(e),route=e.c.JPWNavigation.current().canonical;e.data.set('jpwealth_learning_guide_v1',other);
 if(command==='start')e.c.JPWLearningGuide.start('personal-finance');else e.c.cb[command]();e.flush();
 assert.equal(e.data.get('jpwealth_learning_guide_v1'),other,'competing cursor bytes');assert.equal(e.c.JPWNavigation.current().canonical,route,'route must not change');assert.equal(e.c.JPWLearningGuide.snapshot().paused,true);assert.equal(e.c.JPWLearningGuide.snapshot().stepId,'tools-calendar');
});
