 bounded();e.c.visualViewport.height=400;callbacks.resize.forEach(f=>f());e.flush();bounded();for(let i=0;i<12;i++){e.nestedScroll(card);e.flush();bounded();}assert.equal(e.writes(),writes);e.c.JPWLearningView.hide();assert.equal(callbacks.resize.length,0);
